fn solve(input: Vec<char>) -> Vec<char> {
    // Map each digit character to its good count
    fn good_count(d: char) -> u32 {
        match d {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => 0, // input guarantees first two chars are digits, so this won't happen normally
        }
    }

    // Extract the first two characters (guaranteed to be digits as per problem statement)
    let first_digit = input[0];
    let second_digit = input[1];

    let product = good_count(first_digit) * good_count(second_digit);

    // Convert product (1..=49) to string decimal representation
    let product_str = product.to_string();

    // Collect characters into Vec<char> and append newline
    let mut result: Vec<char> = product_str.chars().collect();
    result.push('\n');

    result
}